  const inputFields = formType.value === 'create' ? ['projectId', 'sampleId', 'entrustmentDate', 'entryDate', 'strengthGrade', 'manufacturer', 'furnaceBatchNumber', 'buildingNo', 'concatPosition', 'representativeBatch', 'numberOfPieces', 'batchNumber', 'remarks', 'testNumber', 'testingConclusion', 'syBs'] : ['id', 'projectId', 'sampleId', 'entrustmentDate', 'entryDate', 'strengthGrade', 'manufacturer', 'furnaceBatchNumber', 'buildingNo', 'concatPosition', 'representativeBatch', 'numberOfPieces', 'batchNumber', 'remarks', 'testNumber', 'testingConclusion', 'syBs']
